package com.bank.proj.repository;

import com.bank.proj.model.Account;
import com.bank.proj.view.AccountView;
import com.bank.proj.dto.AccountDto;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.List;
import java.util.Optional;

public interface AccountRepository extends JpaRepository<Account, String> {

    // interface projection — selects only getId/getBalance columns
    List<AccountView> findAllProjectedBy();

    // DTO/constructor-expression projection — selects exact fields
    @Query("select new com.bank.proj.dto.AccountDto(a.id, a.holderName, a.balance) " +
           "from Account a")
    List<AccountDto> findAllAsDto();

    // dynamic projection — caller chooses the shape at runtime
    <T> Optional<T> findById(String id, Class<T> type);
}
