package com.bank.proj.service;

import com.bank.proj.model.Account;
import com.bank.proj.repository.AccountRepository;
import com.bank.proj.view.AccountView;
import com.bank.proj.dto.AccountDto;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class AccountReadService {
    private final AccountRepository repo;

    // lightweight list for dashboard (only id + balance selected)
    @Transactional(readOnly = true)
    public List<AccountView> dashboard() {
        List<AccountView> views = repo.findAllProjectedBy();
        log.info("Dashboard loaded {} projected rows (id+balance only)", views.size());
        return views;
    }

    // immutable DTOs for API response
    @Transactional(readOnly = true)
    public List<AccountDto> apiList() {
        return repo.findAllAsDto();  // SELECT id, holder_name, balance only
    }

    // dynamic: full entity OR DTO depending on flag
    @Transactional(readOnly = true)
    public Object getOne(String id, boolean summary) {
        return summary
            ? repo.findById(id, AccountDto.class).orElseThrow()   // light
            : repo.findById(id, Account.class).orElseThrow();     // full entity
    }
}
